import { useCallback, useEffect, useState } from 'react';
import {
  View,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
  ActivityIndicator,
} from 'react-native';
import {
  listMessages,
  sendText,
  markRead,
  connectWs,
} from '../api/client';
import { useAuth } from '../session/AuthContext';
import { theme } from '../theme';
import { Composer } from '../components/Composer';
import { MessageList } from '../components/MessageList';
import type { ChatMessage } from '../components/MessageBubble';
import type { MessageStatus } from '../components/Tick';

export type ChatScreenProps = {
  route: { params: { chatId: string; title: string } };
};

function sortNewestFirst(items: ChatMessage[]): ChatMessage[] {
  return [...items].sort(
    (a, b) =>
      new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime() ||
      b.id.localeCompare(a.id),
  );
}

export function ChatScreen({ route }: ChatScreenProps) {
  const { chatId } = route.params;
  const { user } = useAuth();
  const currentUserId = user?.id ?? '';
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [loading, setLoading] = useState(true);

  const appendMessage = useCallback((msg: ChatMessage) => {
    setMessages((prev) => {
      if (prev.some((m) => m.id === msg.id)) {
        return prev;
      }
      return sortNewestFirst([msg, ...prev]);
    });
  }, []);

  const updateStatus = useCallback(
    (messageId: string, status: MessageStatus) => {
      setMessages((prev) =>
        prev.map((m) => (m.id === messageId ? { ...m, status } : m)),
      );
    },
    [],
  );

  useEffect(() => {
    let cancelled = false;

    (async () => {
      setLoading(true);
      try {
        const items = await listMessages(chatId);
        if (!cancelled) {
          setMessages(sortNewestFirst(items as ChatMessage[]));
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    })();

    const disconnect = connectWs({
      onMessageNew: (msg) => {
        const next = msg as ChatMessage;
        if (next.chatId === chatId) {
          appendMessage(next);
        }
      },
      onMessageStatus: (payload) => {
        const { messageId, status, chatId: statusChatId } = payload as {
          messageId: string;
          status: MessageStatus;
          chatId?: string;
        };
        if (statusChatId && statusChatId !== chatId) {
          return;
        }
        updateStatus(messageId, status);
      },
    });

    return () => {
      cancelled = true;
      disconnect?.();
    };
  }, [chatId, appendMessage, updateStatus]);

  const handleSendText = useCallback(
    async (text: string) => {
      const sent = (await sendText(chatId, text)) as ChatMessage;
      appendMessage(sent);
      const lastId = sent.id;
      if (lastId) {
        await markRead(chatId, lastId);
      }
    },
    [chatId, appendMessage],
  );

  const handleAudioSent = useCallback(
    (msg: ChatMessage) => {
      appendMessage(msg);
      void markRead(chatId, msg.id);
    },
    [appendMessage, chatId],
  );

  return (
    <KeyboardAvoidingView
      style={styles.flex}
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      keyboardVerticalOffset={Platform.OS === 'ios' ? 88 : 0}
    >
      <View style={styles.container}>
        {loading ? (
          <View style={styles.loader}>
            <ActivityIndicator color={theme.colors.accent} />
          </View>
        ) : (
          <MessageList messages={messages} currentUserId={currentUserId} />
        )}
        <Composer
          chatId={chatId}
          onSent={handleAudioSent}
          onSendText={handleSendText}
        />
      </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  flex: {
    flex: 1,
    backgroundColor: theme.colors.bg,
  },
  container: {
    flex: 1,
    backgroundColor: theme.colors.bg,
  },
  loader: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
});

export default ChatScreen;
EOF"
